#!/usr/bin/env node
/**
 * The runtime conformance suite: a foreign runtime against the fixture
 * (T6.4, REQ-STD-2, REQ-STD-3, LLD §14).
 *
 *   node scripts/runtime-conformance.mjs [--runtime java] [--report reports/runtime-java.md]
 *
 * > Runtime suite: plans plus bindings plus expected `results.jsonl` (status and
 * > matched `by`) generated by the TS runtime on the sample app; a foreign
 * > runtime passes when statuses and matched candidates are identical.
 *
 * ## What is compared, and what is not
 *
 * Per step, in plan order: the **status** and the **matched candidate** — its
 * index and its `by`. Nothing else. Timestamps, durations, run ids and the `ref`
 * a runtime minted for an element belong to the run rather than to the plan, and
 * comparing them would be comparing two clocks.
 *
 * The matched candidate is the part that makes this worth running. Two runtimes
 * can produce the same statuses by finding the same elements different ways —
 * one by test id, one by XPath — and that is a difference that will bite the
 * first time a page changes. LLD §14 requires both, so both are compared.
 *
 * ## Why the fixture and not a fresh TypeScript run
 *
 * `evals/conformance/runtime/results.jsonl` is committed, produced by
 * `scripts/compatibility.mjs`, and is what REQ-STD-2 publishes for third
 * parties. Comparing against it is comparing against the published artifact
 * rather than against whatever this checkout happens to do today.
 */
import { spawn, spawnSync } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { startSampleApp } from "sample-web";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const PROJECT = join(ROOT, "evals", "fixtures");
const FIXTURE = join(ROOT, "evals", "conformance", "runtime");
const CLI = join(ROOT, "packages", "cli", "dist", "bin.js");

const args = process.argv.slice(2);
const option = (name, fallback) => {
  const at = args.indexOf(`--${name}`);
  return at < 0 ? fallback : args[at + 1];
};
const runtime = option("runtime", "java");
const report = option("report", join(ROOT, "reports", `runtime-${runtime}.md`));

/** The four flows the fixture holds; the fifth is the policy showcase (T2.10). */
const FLOWS = [
  "flows/simple.flow",
  "flows/svatah.flow",
  "flows/natural_language_login.flow",
  "flows/execution.flow",
];

/** Fixed, so the foreign runtime types the same characters the fixture did. */
const SECRETS = {
  SVATAH_SAMPLE_PASSWORD: "qwerty123",
  SVATAH_SAMPLE_CARD_NUMBER: "5123456789012346",
  SVATAH_SAMPLE_CARD_CVV: "123",
};

const die = (code, message) => {
  process.stderr.write(`${message}\n`);
  process.exit(code);
};

if (!existsSync(CLI)) die(2, "Run `pnpm -r build` first: the plan is compiled by the CLI.");

const jar = join(ROOT, "runtimes", "java", "build", "libs", "svatah-runtime-java-0.1.0-all.jar");
if (runtime === "java" && !existsSync(jar)) {
  die(
    2,
    `The Java runtime is not built (${jar}).\n` +
      "Run: cd runtimes/java && ./gradlew fatJar",
  );
}

/** What LLD §14 compares: status and matched candidate, per step, in order. */
const comparable = (result) => ({
  flow: result.flow,
  story: result.story,
  stepId: result.stepId,
  status: result.status,
  matched:
    result.matched === undefined
      ? null
      : { candidateIndex: result.matched.candidateIndex, by: result.matched.by },
});

const readResults = (path) => {
  const text = readFileSync(path, "utf8").trim();
  return text === "" ? [] : text.split("\n").map((line) => JSON.parse(line));
};

const expected = readResults(join(FIXTURE, "results.jsonl"));

const app = await startSampleApp(0);
const workspace = mkdtempSync(join(tmpdir(), "svatah-conformance-"));
let exitCode = 0;

try {
  /*
   * The plan the fixture was produced from, compiled the same way — `--stable`,
   * so `plan.sha256` can be checked before anything runs. A foreign runtime
   * executing a *different* plan would pass or fail for reasons that have
   * nothing to do with the runtime.
   */
  const planPath = join(workspace, "plan.json");
  const compile = spawnSync(
    process.execPath,
    [CLI, "compile", PROJECT, "--stable", "--out", planPath],
    { encoding: "utf8" },
  );
  if (compile.status !== 0) die(2, `compile failed:\n${compile.stdout}${compile.stderr}`);

  const { createHash } = await import("node:crypto");
  const sha = createHash("sha256").update(readFileSync(planPath, "utf8")).digest("hex");
  const recorded = readFileSync(join(FIXTURE, "plan.sha256"), "utf8").split(" ")[0];
  if (sha !== recorded) {
    die(
      2,
      `The plan is not the one the fixture was produced from.\n` +
        `  compiled: ${sha}\n  fixture:  ${recorded}\n` +
        "Regenerate the fixture with `node scripts/compatibility.mjs` first.",
    );
  }
  process.stderr.write(`plan.json matches the fixture — sha256 ${sha}\n`);

  /* The project the foreign runtime is pointed at: the fixtures, plus the plan. */
  const project = join(workspace, "project");
  mkdirSync(join(project, ".svatah"), { recursive: true });
  for (const entry of ["bindings", "flows", "api", "data.yaml", "svatah.config.yaml"]) {
    spawnSync("cp", ["-R", join(PROJECT, entry), join(project, entry)]);
  }
  writeFileSync(join(project, ".svatah", "plan.json"), readFileSync(planPath, "utf8"));

  const started = Date.now();
  const outcome = await new Promise((done) => {
    let output = "";
    const child = spawn(
      "java",
      [
        "-jar",
        jar,
        project,
        "--run-id",
        "conformance",
        "--base-url",
        app.origin,
        /*
         * The same inputs `scripts/compatibility.mjs` gave the TypeScript run
         * that produced the fixture. `simple.flow`'s login story declares a
         * signature — the hand migration turned two literals into one — so a
         * run without them logs in as nobody and every step after it fails.
         */
        "--input",
        "email=connected2atul@gmail.com",
        "--input",
        `password=${SECRETS.SVATAH_SAMPLE_PASSWORD}`,
        ...FLOWS.flatMap((flow) => ["--flow", flow]),
      ],
      { env: { ...process.env, ...SECRETS } },
    );
    child.stdout.on("data", (chunk) => (output += String(chunk)));
    child.stderr.on("data", (chunk) => (output += String(chunk)));
    child.on("close", (code) => done({ code: code ?? 1, output }));
  });
  process.stderr.write(outcome.output);

  const producedPath = join(project, "runs", "conformance", "results.jsonl");
  if (!existsSync(producedPath)) {
    die(1, `The ${runtime} runtime wrote no results.jsonl.\n${outcome.output}`);
  }
  const produced = readResults(producedPath);

  /* ── the comparison ─────────────────────────────────────────────────────── */

  const mismatches = [];
  const width = Math.max(expected.length, produced.length);
  for (let at = 0; at < width; at += 1) {
    const left = expected[at];
    const right = produced[at];
    const a = left === undefined ? null : comparable(left);
    const b = right === undefined ? null : comparable(right);
    if (JSON.stringify(a) === JSON.stringify(b)) continue;
    mismatches.push({ at, expected: a, produced: b });
  }

  const lines = [
    `# Runtime conformance — \`${runtime}\``,
    "",
    `Run at ${new Date().toISOString()} · ${Date.now() - started} ms`,
    "",
    `Fixture: \`evals/conformance/runtime\` (plan \`${sha.slice(0, 12)}…\`)`,
    "",
    mismatches.length === 0
      ? `**Conformant.** ${expected.length} step results, **zero mismatches** in status and ` +
        "matched candidate (REQ-STD-3, LLD §14)."
      : `**Not conformant.** ${mismatches.length} of ${width} step results differ.`,
    "",
    "| # | flow | story | step | status | matched |",
    "|---|---|---|---|---|---|",
  ];
  for (let at = 0; at < expected.length; at += 1) {
    const one = comparable(expected[at]);
    const differs = mismatches.some((m) => m.at === at);
    lines.push(
      `| ${at} | \`${one.flow}\` | ${one.story} | \`${one.stepId}\` | ` +
        `${differs ? "**≠** " : ""}${one.status} | ` +
        `${one.matched === null ? "—" : `${one.matched.by} #${one.matched.candidateIndex}`} |`,
    );
  }

  if (mismatches.length > 0) {
    lines.push("", "## Mismatches", "");
    for (const one of mismatches) {
      lines.push(`### step ${one.at}`, "");
      lines.push("```diff");
      lines.push(`- expected  ${JSON.stringify(one.expected)}`);
      lines.push(`+ produced  ${JSON.stringify(one.produced)}`);
      lines.push("```", "");
    }
    exitCode = 1;
  }

  mkdirSync(dirname(resolve(report)), { recursive: true });
  writeFileSync(resolve(report), `${lines.join("\n")}\n`, "utf8");

  process.stdout.write(
    mismatches.length === 0
      ? `${runtime}: conformant — ${expected.length} step results, zero mismatches → ${report}\n`
      : `${runtime}: NOT conformant — ${mismatches.length} of ${width} differ → ${report}\n`,
  );
  for (const one of mismatches.slice(0, 10)) {
    process.stdout.write(
      `  step ${one.at}\n    expected ${JSON.stringify(one.expected)}\n` +
        `    produced ${JSON.stringify(one.produced)}\n`,
    );
  }
} finally {
  await app.close();
  rmSync(workspace, { recursive: true, force: true });
}

process.exit(exitCode);
